"""Prepare the bounded, trilingual 3D section from the approved site baseline."""
import argparse,hashlib,json,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
parser=argparse.ArgumentParser();parser.add_argument('--case',required=True);parser.add_argument('--runtime',required=True);parser.add_argument('--baseline');args=parser.parse_args()
CASE=Path(args.case).resolve();SKILL=Path(args.runtime).resolve()
if shutil.disk_usage(ROOT).free<2*1024**3+30*1024**2:raise RuntimeError('D reserve')
UI={
'en':{'eyebrow':'INTERACTIVE EQUIPMENT','title':'Explore the equipment in 3D','description':'Rotate, zoom and inspect the blade, base frame and drive assembly from different angles.','launch':'View in 3D','loading':'Loading 3D view…','poster':'Exterior visualization of equipment 01','frameTitle':'Interactive 3D equipment view','note':'Reference-based exterior visualization. Dimensions and final configuration are confirmed for each project.','full':'Open full 3D view','hint':'Drag to rotate · Scroll or pinch to zoom','interactive':'INTERACTIVE 3D','name':'Equipment 01','instruction':'Drag to rotate. Scroll or pinch to zoom.','viewLabel':'Choose a view','reset':'Reset view','auto':'Auto rotate','pause':'Pause rotation','zoomIn':'Zoom in','zoomOut':'Zoom out','keyboard':'Keyboard: arrows rotate, + / − zoom, 0 resets.','ready':'Ready to explore','unavailable':'3D is unavailable in this browser. The equipment image is shown instead.','views':{'overview':'Overview','sideA':'Front','sideB':'Drive side','endA':'End A','endB':'End B','top':'Hopper','blade':'Blade','frame':'Base frame','frontDetail':'Front plates'}},
'th':{'eyebrow':'สำรวจอุปกรณ์แบบอินเทอร์แอคทีฟ','title':'สำรวจอุปกรณ์ในแบบ 3D','description':'หมุน ซูม และดูใบมีด โครงฐาน และชุดขับเคลื่อนจากมุมต่าง ๆ','launch':'ดูแบบ 3D','loading':'กำลังโหลดมุมมอง 3D…','poster':'ภาพจำลองภายนอกของอุปกรณ์ 01','frameTitle':'มุมมองอุปกรณ์ 3D แบบอินเทอร์แอคทีฟ','note':'ภาพจำลองภายนอกอ้างอิงจากภาพถ่ายจริง ขนาดและรูปแบบอุปกรณ์ขั้นสุดท้ายจะยืนยันสำหรับแต่ละโครงการ','full':'เปิดมุมมอง 3D แบบเต็ม','hint':'ลากเพื่อหมุน · เลื่อนหรือใช้สองนิ้วเพื่อซูม','interactive':'มุมมอง 3D แบบอินเทอร์แอคทีฟ','name':'อุปกรณ์ 01','instruction':'ลากเพื่อหมุน เลื่อนหรือใช้สองนิ้วเพื่อซูม','viewLabel':'เลือกมุมมอง','reset':'รีเซ็ตมุมมอง','auto':'หมุนอัตโนมัติ','pause':'หยุดการหมุน','zoomIn':'ซูมเข้า','zoomOut':'ซูมออก','keyboard':'แป้นพิมพ์: ลูกศรเพื่อหมุน + / − เพื่อซูม และ 0 เพื่อรีเซ็ต','ready':'พร้อมสำรวจ','unavailable':'เบราว์เซอร์นี้ไม่สามารถแสดง 3D ได้ จึงแสดงภาพอุปกรณ์แทน','views':{'overview':'ภาพรวม','sideA':'ด้านหน้า','sideB':'ด้านชุดขับเคลื่อน','endA':'ด้านปลาย A','endB':'ด้านปลาย B','top':'ถังป้อน','blade':'ใบมีด','frame':'โครงฐาน','frontDetail':'แผ่นด้านหน้า'}},
'id':{'eyebrow':'PERALATAN INTERAKTIF','title':'Jelajahi peralatan dalam 3D','description':'Putar, perbesar, dan lihat bilah, rangka dasar, serta unit penggerak dari berbagai sudut.','launch':'Lihat dalam 3D','loading':'Memuat tampilan 3D…','poster':'Visualisasi bagian luar peralatan 01','frameTitle':'Tampilan peralatan 3D interaktif','note':'Visualisasi bagian luar berdasarkan foto referensi. Dimensi dan konfigurasi akhir dikonfirmasi untuk setiap proyek.','full':'Buka tampilan 3D penuh','hint':'Seret untuk memutar · Gulir atau cubit untuk memperbesar','interactive':'TAMPILAN 3D INTERAKTIF','name':'Peralatan 01','instruction':'Seret untuk memutar. Gulir atau cubit untuk memperbesar.','viewLabel':'Pilih tampilan','reset':'Atur ulang','auto':'Putar otomatis','pause':'Jeda putaran','zoomIn':'Perbesar','zoomOut':'Perkecil','keyboard':'Papan ketik: panah untuk memutar, + / − untuk zoom, 0 untuk mengatur ulang.','ready':'Siap dijelajahi','unavailable':'3D tidak tersedia di peramban ini. Gambar peralatan ditampilkan sebagai gantinya.','views':{'overview':'Keseluruhan','sideA':'Depan','sideB':'Sisi penggerak','endA':'Ujung A','endB':'Ujung B','top':'Hopper','blade':'Bilah','frame':'Rangka dasar','frontDetail':'Pelat depan'}}}
OUTER=['eyebrow','title','description','launch','loading','poster','frameTitle','note','full','hint']
for lang,strings in UI.items():
    p=ROOT/f'content/{lang}.json';catalog=json.loads(p.read_text('utf-8'))
    catalog.update({f'equipment3d.{key}':strings[key] for key in OUTER})
    p.write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n','utf-8')
(ROOT/'source/data/equipment-3d-ui.json').write_text(json.dumps(UI,ensure_ascii=False,indent=2)+'\n','utf-8')
provenance_file=ROOT/'source/data/equipment-3d-provenance.json'
prior_provenance=json.loads(provenance_file.read_text('utf-8')) if provenance_file.exists() else {}
source_spec=json.loads((CASE/'model-spec.json').read_text('utf-8'))
spec={'schema_version':1,'name':'Equipment 01','materials':source_spec['materials'],
      'parts':[{k:v for k,v in p.items() if k not in {'evidence','label','status','note','group'}} for p in source_spec['parts']],
      'views':[{k:v for k,v in p.items() if k not in {'reference','label'}} for p in source_spec['views']]}
(ROOT/'source/data/equipment-3d-model.json').write_text(json.dumps(spec,ensure_ascii=False,separators=(',',':')),'utf-8')
shutil.copy2(SKILL/'assets/model.mjs',ROOT/'source/equipment3d/model.mjs')
provenance={'date':'2026-10-12','timezone':'Asia/Shanghai','source_revision':source_spec.get('revision','v001'),'source_model_sha256':hashlib.sha256((CASE/'model-spec.json').read_bytes()).hexdigest(),'original_3d_appearance_accepted':False,'user_authorized_website_reuse_and_publication':True,'public_scope':'Equipment-page interactive exterior visualization; no connection to any specific reference configuration is asserted.','public_assets_exclude':['original videos','workshop reference photos','private file paths','local provenance notes','commercial documents'],'languages':['en','th','id'],'translations':'Agent translation and terminology review; no Google-generated draft claimed','baseline_commit':args.baseline or prior_provenance.get('baseline_commit','57bc3b61f36ed68459228188b92b8fa8eca5843a'),'unpublished_GEO_changes':'Kept in the original checkout and excluded from this release','autoplay':'Loads automatically without clicking; gentle turntable runs when visible, pauses offscreen or in a background tab; reduced-motion preference starts still'}
for key in ['initial_baseline_commit','concurrent_watermark_update_preserved','new_poster_watermark','concurrent_svg_hash_fix_preserved']:
    if key in prior_provenance:provenance[key]=prior_provenance[key]
(ROOT/'source/data/equipment-3d-provenance.json').write_text(json.dumps(provenance,ensure_ascii=False,indent=2)+'\n','utf-8')
section='''<section class="equipment-3d" id="equipment-3d"><div class="wrap">
<div class="section-top"><div><div class="eyebrow">{{t:equipment3d.eyebrow}}</div><h2>{{t:equipment3d.title}}</h2></div><p>{{t:equipment3d.description}}</p></div>
<div class="equipment-3d-shell" data-equipment-3d aria-busy="false"><div class="equipment-3d-poster"><img src="/assets/equipment3d/equipment01-poster.webp" alt="{{a:equipment3d.poster}}" width="1600" height="1000" loading="lazy" decoding="async"><button class="btn primary equipment-3d-launch" type="button" data-load-3d aria-controls="equipment-3d-frame" hidden><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="m12 3 9 5v8l-9 5-9-5V8zM3 8l9 5 9-5M12 13v8"/></svg>{{t:equipment3d.launch}}</button></div>
<iframe id="equipment-3d-frame" data-src="/assets/equipment3d/viewer.html?lang={{lang}}" title="{{a:equipment3d.frameTitle}}" hidden></iframe><div class="equipment-3d-state" role="status" aria-live="polite" hidden>{{t:equipment3d.loading}}</div></div>
<div class="equipment-3d-caption"><p>{{t:equipment3d.note}}</p><a href="/assets/equipment3d/viewer.html?lang={{lang}}" target="_blank" rel="noopener">{{t:equipment3d.full}} ↗</a></div><span class="equipment-3d-hint">{{t:equipment3d.hint}}</span>
</div></section>'''
template=ROOT/'source/templates/equipment.html';text=template.read_text('utf-8')
if 'id="equipment-3d"' not in text:
    anchor='<section class="equipment-gallery" id="equipment-gallery">';assert text.count(anchor)==1;text=text.replace(anchor,section+anchor,1)
if '/assets/equipment-3d.css' not in text:text=text.replace('{{equipment_reference_styles}}','{{equipment_reference_styles}}<link rel="stylesheet" href="/assets/equipment-3d.css"><script src="/assets/equipment-3d.js" defer></script>',1)
text=text.replace('alt="{{a:equipment3d.poster}}" width="1440" height="1000"','alt="{{a:equipment3d.poster}}" width="1600" height="1000"')
template.write_text(text,'utf-8')
print(json.dumps({'languages':list(UI),'parts':len(spec['parts']),'views':len(spec['views']),'public_model_bytes':(ROOT/'source/data/equipment-3d-model.json').stat().st_size}))
